<#
.SYNOPSIS
    Generate the embedded Cloak build manifest header from build-identity.json.

.DESCRIPTION
    Verifies build-identity.json with verify-manifest.ps1, then writes a
    CloakBuildIdentity.h that defines g_CloakBuildManifest for
    VBOX_WITH_CLOAK_BUILD builds. The header is generated into the source tree
    before kmk runs; it is intentionally not committed.

.PARAMETER ManifestPath
    Path to the verified build-identity.json.

.PARAMETER OutputPath
    Destination path for CloakBuildIdentity.h.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][string] $ManifestPath,
    [Parameter(Mandatory = $true)][string] $OutputPath
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Import-Module (Join-Path $PSScriptRoot 'CloakManifest.psm1') -Force

$Verifier = Join-Path $PSScriptRoot 'verify-manifest.ps1'
& $Verifier -ManifestPath $ManifestPath -RequireCloak
if ($LASTEXITCODE -ne 0) {
    throw "verify-manifest.ps1 rejected the cloak manifest: exit $LASTEXITCODE"
}

$ResolvedManifest = (Resolve-Path -LiteralPath $ManifestPath).Path
$Json = Get-Content -LiteralPath $ResolvedManifest -Raw | ConvertFrom-Json

function ConvertTo-CloakCString {
    param($Value)
    if ($null -eq $Value) {
        return 'NULL'
    }
    $Text = [string] $Value
    $Builder = [System.Text.StringBuilder]::new()
    [void] $Builder.Append('"')
    foreach ($Character in $Text.ToCharArray()) {
        $Code = [int] $Character
        if ($Character -eq '\') {
            [void] $Builder.Append('\\')
        }
        elseif ($Character -eq '"') {
            [void] $Builder.Append('\"')
        }
        elseif ($Code -lt 0x20 -or $Code -gt 0x7E) {
            throw "manifest value contains non-ASCII or control character 0x$('{0:X2}' -f $Code)"
        }
        else {
            [void] $Builder.Append($Character)
        }
    }
    [void] $Builder.Append('"')
    return $Builder.ToString()
}

$BuildMode = Get-CloakStringOrNull $Json 'buildMode'
$FirmwareFamily = Get-CloakStringOrNull $Json 'firmwareFamily'
$PcBiosVersion = Get-CloakStringOrNull $Json 'pcBiosVersion'
$OvmfVersion = Get-CloakStringOrNull $Json 'ovmfVersion'
$DsdtHash = Get-CloakStringOrNull $Json 'dsdtHash'
$VgaBiosHash = Get-CloakStringOrNull $Json 'vgaBiosHash'
$BiosRomHash = Get-CloakStringOrNull $Json 'biosRomHash'
$SourceRevision = Get-CloakStringOrNull $Json 'sourceRevision'
$BuildHash = Get-CloakStringOrNull $Json 'buildHash'
$ChipsetProperty = $Json.PSObject.Properties['supportedChipsets']
if (-not $ChipsetProperty) {
    throw "missing property 'supportedChipsets'"
}
$ChipsetMask = Get-CloakChipsetMask $ChipsetProperty.Value

$Header = @"
/*
 * Generated by .github/scripts/generate-build-identity-header.ps1.
 * Do not edit; regenerate from build-identity.json.
 */
#ifndef CLOAK_BUILD_IDENTITY_H
#define CLOAK_BUILD_IDENTITY_H

#include "ConsoleImplConfigCloak.h"

#ifndef VBOX_WITH_CLOAK_BUILD
# error "CloakBuildIdentity.h is only valid in VBOX_WITH_CLOAK_BUILD builds"
#endif

static const CLOAKBUILDMANIFEST g_CloakBuildManifest =
{
    $(ConvertTo-CloakCString $BuildMode),
    $(ConvertTo-CloakCString $FirmwareFamily),
    $(ConvertTo-CloakCString $PcBiosVersion),
    $(ConvertTo-CloakCString $OvmfVersion),
    $(ConvertTo-CloakCString $DsdtHash),
    $(ConvertTo-CloakCString $VgaBiosHash),
    $(ConvertTo-CloakCString $BiosRomHash),
    $(('{0}U' -f $ChipsetMask)),
    CLOAKBINDING_VMMDEV_VENDOR_ID,
    CLOAKBINDING_VMMDEV_DEVICE_ID,
    CLOAKBINDING_VGA_VENDOR_ID,
    CLOAKBINDING_VGA_DEVICE_ID,
    CLOAKBINDING_VIRTIO_VENDOR_ID,
    $(ConvertTo-CloakCString $SourceRevision),
    $(ConvertTo-CloakCString $BuildHash)
};

#endif /* CLOAK_BUILD_IDENTITY_H */
"@

$ResolvedOutput = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)
$OutputDir = Split-Path -Parent $ResolvedOutput
if ($OutputDir -and -not (Test-Path -LiteralPath $OutputDir)) {
    New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
}
[System.IO.File]::WriteAllText($ResolvedOutput, $Header, [System.Text.UTF8Encoding]::new($false))

Write-Host "Wrote embedded build identity header: $ResolvedOutput"
Write-Host "  buildMode=$BuildMode sourceRevision=$SourceRevision buildHash=$BuildHash"
exit 0
